"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7285],{51594:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a nuisance prop and, on the owner\'s client only, attaches the \\"Clear\\"\\nprompt described on [Nuisance]. No prompt is created if demolition has already\\nstarted.","params":[{"name":"propData","desc":"","lua_type":"PropBaseClass.PropData"}],"returns":[{"desc":"","lua_type":"Nuisance"}],"function_type":"static","source":{"line":67,"path":"src/Shared/Class/Base/Props/Nuisance.luau"}}],"properties":[],"types":[{"name":"Nuisance","desc":"Instance shape of a nuisance, on top of everything inherited from\\n[PropBaseClass].","fields":[{"name":"destroyPrompt","lua_type":"ProximityPrompt?","desc":"The \\"Clear\\" prompt; owner\'s client only"}],"source":{"line":50,"path":"src/Shared/Class/Base/Props/Nuisance.luau"}}],"name":"Nuisance","desc":"A prop that exists to be cleared. Nuisances are the obstacles that occupy a\\nplot when a player first gets it \u2014 rocks, trees, overgrown fields \u2014 and the\\nwhole class is a single \\"Clear\\" prompt on top of [PropBaseClass].\\n`Rock.luau`, `Tree.luau` and `Field.luau` are aliases for this module; the\\ndifferences between them are entirely in item data.\\n\\nThe prompt is created only on the owner\'s client, and only when the prop is\\nnot already being demolished. Triggering it takes one of two paths depending\\non the item\'s data:\\n\\n- Items with a `destroyTime` dispatch `BASE_START_PROP_DESTRUCTION`, which\\n  starts the timed demolition countdown; the prop stays visible with a\\n  progress bar until it elapses.\\n- Items without one dispatch `BASE_REMOVE_PROP` and vanish immediately.\\n\\nEither way the prompt destroys itself, and a replica listener also tears it\\ndown if demolition is started from somewhere else \u2014 so a nuisance can never\\nbe queued for removal twice.\\n\\nGated by [FeatureFlags].BaseEnabled \u2014 disabled by default; per-project forks\\nenable it deliberately.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","tags":["dormant"],"source":{"line":30,"path":"src/Shared/Class/Base/Props/Nuisance.luau"}}')}}]);